import * as React from "react";

import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Slider } from "@/registry/erbium/ui/slider";

export const SliderControlled = () => {
  const [value, setValue] = React.useState([0.3, 0.7]);

  return (
    <Field className="mx-auto max-w-xs gap-related">
      <div className="flex items-center justify-between gap-related">
        <FieldLabel>Temperature</FieldLabel>
        <span className="text-caption text-muted-foreground">{value.join(", ")}</span>
      </div>
      <Slider
        value={value}
        onValueChange={(next) => {
          setValue(next);
        }}
        min={0}
        max={1}
        step={0.1}
      />
    </Field>
  );
};

import { SliderControlled } from "../examples/slider-controlled";

const Example = () => <SliderControlled />;

export default Example;
